1	"use client";
2	
3	// Real xAI Grok voice engine over a DIRECT browser→xAI WebSocket.
4	//
5	// Architecture (no relay server): mint an ephemeral client-secret at
6	// /api/xai/token, then open `wss://api.x.ai/v1/realtime` carrying the token in
7	// the subprotocol (browsers can't set WS headers). We own the whole audio
8	// pipeline: mic → PCM16 → `input_audio_buffer.append`; inbound
9	// `response.output_audio.delta` → PCM16 → AudioBuffer playback. Barge-in is
10	// server-VAD driven (`input_audio_buffer.speech_started` → stop playback).
11	//
12	// Exposes a surface deliberately parallel to @elevenlabs/react's useConversation
13	// so useRealtimeSession can dispatch to either engine uniformly. Must be called
14	// unconditionally (rules of hooks); it stays inert until start().
15	
16	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
17	import type { Persona } from "@/lib/data";
18	import type { CallState, SessionTurn } from "./types";
19	import { resolveXaiAgent } from "./xai-agent";
20	import {
21	  base64Pcm16ToFloat32,
22	  calculateRms,
23	  EarlyAudioBuffer,
24	  float32ToPcm16Base64,
25	  PlaybackQueue,
26	} from "./xai-audio";
27	
28	const REALTIME_BASE = "wss://api.x.ai/v1/realtime";
29	const CHUNK_MS = 100;
30	const VOL_GAIN = 3.5;
31	
32	export interface XaiSession {
33	  callState: CallState;
34	  turns: SessionTurn[];
35	  caption: string;
36	  start: () => void;
37	  stop: () => void;
38	  interrupt: () => void;
39	  setMuted: (muted: boolean) => void;
40	  getInputVolume: () => number;
41	  getOutputVolume: () => number;
42	}
43	
44	type XaiEvent = {
45	  type: string;
46	  delta?: string;
47	  transcript?: string;
48	  error?: { type?: string; code?: string; message?: string };
49	  item?: { role?: string; content?: Array<{ type?: string; transcript?: string; text?: string }> };
50	};
51	
52	function extractToken(data: unknown): string | null {
53	  if (typeof data !== "object" || data === null) return null;
54	  const d = data as Record<string, unknown>;
55	  if (typeof d.value === "string") return d.value;
56	  if (typeof d.token === "string") return d.token;
57	  if (typeof d.secret === "string") return d.secret;
58	  const cs = d.client_secret;
59	  if (typeof cs === "string") return cs;
60	  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
61	    return (cs as Record<string, unknown>).value as string;
62	  }
63	  return null;
64	}
65	
66	export function useXaiSession(active: boolean, persona?: Persona): XaiSession {
67	  const [callState, setCallState] = useState<CallState>("idle");
68	  const [turns, setTurns] = useState<SessionTurn[]>([]);
69	  const [caption, setCaption] = useState("press CALL to begin");
70	
71	  const wsRef = useRef<WebSocket | null>(null);
72	  const ctxRef = useRef<AudioContext | null>(null);
73	  const streamRef = useRef<MediaStream | null>(null);
74	  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
75	  const procRef = useRef<ScriptProcessorNode | null>(null);
76	  const playbackRef = useRef<PlaybackQueue | null>(null);
77	  // Early mic audio captured before the session is configured (parallel init).
78	  const earlyBufRef = useRef<EarlyAudioBuffer | null>(null);
79	  // True once `session.updated` arrives: append chunks stream live; until then
80	  // they accumulate in earlyBufRef.
81	  const streamingRef = useRef(false);
82	
83	  const mutedRef = useRef(false);
84	  const endedRef = useRef(false);
85	  const configuredRef = useRef(false);
86	  const inputRmsRef = useRef(0);
87	  const turnSeqRef = useRef(0);
88	  const agentTurnIdRef = useRef<string | null>(null);
89	  const agentBufRef = useRef("");
90	  const interruptTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
91	  const stateRef = useRef<CallState>("idle");
92	  stateRef.current = callState;
93	  // Latest selected persona, read at start() time (avoids stale closures).
94	  const personaRef = useRef(persona);
95	  personaRef.current = persona;
96	
97	  const teardown = useCallback(() => {
98	    if (interruptTimerRef.current) {
99	      clearTimeout(interruptTimerRef.current);
100	      interruptTimerRef.current = null;
101	    }
102	    if (procRef.current) {
103	      procRef.current.onaudioprocess = null;
104	      procRef.current.disconnect();
105	      procRef.current = null;
106	    }
107	    if (sourceRef.current) {
108	      sourceRef.current.disconnect();
109	      sourceRef.current = null;
110	    }
111	    if (streamRef.current) {
112	      streamRef.current.getTracks().forEach((t) => t.stop());
113	      streamRef.current = null;
114	    }
115	    if (playbackRef.current) {
116	      playbackRef.current.stop();
117	      playbackRef.current = null;
118	    }
119	    if (wsRef.current) {
120	      try {
121	        wsRef.current.close();
122	      } catch {
123	        // already closing
124	      }
125	      wsRef.current = null;
126	    }
127	    if (ctxRef.current) {
128	      void ctxRef.current.close();
129	      ctxRef.current = null;
130	    }
131	    configuredRef.current = false;
132	    streamingRef.current = false;
133	    earlyBufRef.current = null;
134	    agentTurnIdRef.current = null;
135	    agentBufRef.current = "";
136	    inputRmsRef.current = 0;
137	  }, []);
138	
139	  const send = useCallback((obj: unknown) => {
140	    const ws = wsRef.current;
141	    if (ws && ws.readyState === WebSocket.OPEN) ws.send(JSON.stringify(obj));
142	  }, []);
143	
144	  const start = useCallback(() => {
145	    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
146	    endedRef.current = false;
147	    configuredRef.current = false;
148	    streamingRef.current = false;
149	    setTurns([]);
150	    setCallState("connecting");
151	    setCaption("establishing session…");
152	
153	    const fail = (msg: string) => {
154	      endedRef.current = true;
155	      teardown();
156	      setCallState("ended");
157	      setCaption(msg);
158	    };
159	
160	    // 1) Bring up audio + mic capture IMMEDIATELY, in parallel with the token
161	    //    mint + WS connect (xAI "parallel initialization"). Native AudioContext
162	    //    rate is advertised to xAI so no resampling is needed. Early PCM is
163	    //    buffered (earlyBufRef) until `session.updated`, then flushed — so the
164	    //    first words spoken right after CALL aren't lost.
165	    const ctx = new AudioContext();
166	    ctxRef.current = ctx;
167	    const rate = ctx.sampleRate;
168	    playbackRef.current = new PlaybackQueue(ctx);
169	    earlyBufRef.current = new EarlyAudioBuffer();
170	
171	    // Local mutable capture buffers (live as long as the processor node).
172	    let pending: Float32Array[] = [];
173	    let total = 0;
174	    const chunkSize = Math.floor((rate * CHUNK_MS) / 1000);
175	
176	    const startCapture = async () => {
177	      try {
178	        const stream = await navigator.mediaDevices.getUserMedia({
179	          audio: {
180	            channelCount: 1,
181	            echoCancellation: true,
182	            noiseSuppression: true,
183	            autoGainControl: true,
184	          },
185	        });
186	        if (endedRef.current) {
187	          // Hung up (or failed) while the mic prompt was open.
188	          stream.getTracks().forEach((t) => t.stop());
189	          return;
190	        }
191	        streamRef.current = stream;
192	        if (ctx.state === "suspended") await ctx.resume();
193	        const source = ctx.createMediaStreamSource(stream);
194	        sourceRef.current = source;
195	        const proc = ctx.createScriptProcessor(4096, 1, 1);
196	        procRef.current = proc;
197	        proc.onaudioprocess = (e) => {
198	          const input = e.inputBuffer.getChannelData(0);
199	          inputRmsRef.current = mutedRef.current ? 0 : calculateRms(input);
200	          if (mutedRef.current) return;
201	          pending.push(new Float32Array(input));
202	          total += input.length;
203	          while (total >= chunkSize) {
204	            const chunk = new Float32Array(chunkSize);
205	            let offset = 0;
206	            while (offset < chunkSize && pending.length > 0) {
207	              const buf = pending[0];
208	              const need = chunkSize - offset;
209	              if (buf.length <= need) {
210	                chunk.set(buf, offset);
211	                offset += buf.length;
212	                total -= buf.length;
213	                pending.shift();
214	              } else {
215	                chunk.set(buf.subarray(0, need), offset);
216	                pending[0] = buf.subarray(need);
217	                offset += need;
218	                total -= need;
219	              }
220	            }
221	            const audio = float32ToPcm16Base64(chunk);
222	            // Stream live once configured; until then accumulate the early audio.
223	            if (streamingRef.current) send({ type: "input_audio_buffer.append", audio });
224	            else earlyBufRef.current?.push(audio);
225	          }
226	        };
227	        source.connect(proc);
228	        // Required in some browsers for the callback to fire; the processor
229	        // writes no output, so this does not echo the mic to the speakers.
230	        proc.connect(ctx.destination);
231	      } catch {
232	        fail("— microphone permission denied —");
233	      }
234	    };
235	
236	    // Kick capture off now — do not await it, and do not wait for the WS.
237	    void startCapture();
238	
239	    void (async () => {
240	      // 2) Mint the ephemeral client-secret server-side (in parallel with capture).
241	      let token: string | null = null;
242	      try {
243	        const res = await fetch("/api/xai/token", { method: "POST" });
244	        const data = await res.json();
245	        if (!res.ok) {
246	          fail(`— ${typeof data?.error === "string" ? data.error : "token error"} —`);
247	          return;
248	        }
249	        token = extractToken(data);
250	      } catch {
251	        fail("— could not reach token endpoint —");
252	        return;
253	      }
254	      if (!token) {
255	        fail("— no xAI token returned —");
256	        return;
257	      }
258	      if (endedRef.current) return; // hung up (or mic denied) during fetch
259	
260	      // ── transcript helpers ──────────────────────────────────────────────
261	      // The setTurns updaters must stay PURE (no ref mutation inside): React
262	      // StrictMode double-invokes them, so any id/sequence mutation happens here
263	      // once, before calling setTurns.
264	      const pushAgentDelta = (delta: string) => {
265	        agentBufRef.current += delta;
266	        const text = agentBufRef.current;
267	        setCaption(text);
268	        let id = agentTurnIdRef.current;
269	        if (id) {
270	          const tid = id;
271	          setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
272	        } else {
273	          id = `x${turnSeqRef.current++}`;
274	          agentTurnIdRef.current = id;
275	          const tid = id;
276	          setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
277	        }
278	      };
279	      const finalizeAgent = () => {
280	        const id = agentTurnIdRef.current;
281	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
282	        agentTurnIdRef.current = null;
283	        agentBufRef.current = "";
284	      };
285	      const pushUser = (text: string) => {
286	        if (!text) return;
287	        const tid = `x${turnSeqRef.current++}`;
288	        setTurns((prev) => [...prev, { id: tid, who: "user", text }]);
289	        setCaption(text);
290	      };
291	
292	      // 3) Resolve the active persona's agent config, then open the WS
293	      //    (token rides the subprotocol since browsers can't set WS headers).
294	      const agent = resolveXaiAgent(personaRef.current?.id);
295	      const ws = new WebSocket(`${REALTIME_BASE}?model=${encodeURIComponent(agent.model)}`, [
296	        `xai-client-secret.${token}`,
297	      ]);
298	      wsRef.current = ws;
299	
300	      const configure = () => {
301	        if (configuredRef.current) return;
302	        configuredRef.current = true;
303	        send({
304	          type: "session.update",
305	          session: {
306	            instructions: agent.instructions,
307	            voice: agent.voice,
308	            audio: {
309	              input: { format: { type: "audio/pcm", rate } },
310	              output: { format: { type: "audio/pcm", rate } },
311	            },
312	            turn_detection: agent.turnDetection,
313	            tools: agent.tools,
314	          },
315	        });
316	      };
317	
318	      ws.onmessage = (event) => {
319	        if (endedRef.current) return; // ignore late events after teardown
320	        let msg: XaiEvent;
321	        try {
322	          msg = JSON.parse(typeof event.data === "string" ? event.data : "") as XaiEvent;
323	        } catch {
324	          return;
325	        }
326	        switch (msg.type) {
327	          case "conversation.created":
328	          case "session.created":
329	            configure();
330	            break;
331	          case "session.updated": {
332	            // Session is configured: switch capture to live streaming and flush
333	            // any audio the user already spoke during connect — in order, BEFORE
334	            // the greeting bootstrap — so their opening words reach the model.
335	            streamingRef.current = true;
336	            const buffered = earlyBufRef.current?.drain() ?? [];
337	            for (const audio of buffered) {
338	              send({ type: "input_audio_buffer.append", audio });
339	            }
340	            setCallState("listening");
341	            setCaption("listening…");
342	            // Prompt an opening line so the agent speaks first.
343	            send({
344	              type: "conversation.item.create",
345	              item: {
346	                type: "message",
347	                role: "user",
348	                content: [{ type: "input_text", text: agent.firstMessage }],
349	              },
350	            });
351	            send({ type: "response.create" });
352	            break;
353	          }
354	          case "response.output_audio.delta":
355	            if (msg.delta) {
356	              playbackRef.current?.enqueue(base64Pcm16ToFloat32(msg.delta));
357	              if (stateRef.current !== "interrupted") setCallState("speaking");
358	            }
359	            break;
360	          case "response.output_audio_transcript.delta":
361	            if (msg.delta) pushAgentDelta(msg.delta);
362	            break;
363	          case "response.done":
364	            finalizeAgent();
365	            if (stateRef.current === "speaking") setCallState("listening");
366	            break;
367	          case "input_audio_buffer.speech_started":
368	            // Server VAD detected the user — barge-in: stop the agent audio.
369	            playbackRef.current?.stop();
370	            finalizeAgent();
371	            setCallState("interrupted");
372	            if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
373	            interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
374	            break;
375	          case "input_audio_buffer.committed":
376	          case "input_audio_buffer.speech_stopped":
377	            if (stateRef.current === "interrupted") setCallState("listening");
378	            break;
379	          case "conversation.item.added":
380	          case "conversation.item.created": {
381	            const item = msg.item;
382	            if (item?.role === "user") {
383	              const t = item.content?.find((c) => c.transcript || c.text);
384	              if (t) pushUser((t.transcript ?? t.text ?? "").trim());
385	            }
386	            break;
387	          }
388	          case "error":
389	            // Surface but don't kill — a fatal error will also close the socket.
390	            setCaption(`— ${msg.error?.message ?? "xAI error"} —`);
391	            break;
392	          default:
393	            break;
394	        }
395	      };
396	
397	      ws.onerror = () => {
398	        if (endedRef.current) return;
399	        endedRef.current = true;
400	        teardown();
401	        setCallState("ended");
402	        setCaption("— connection error —");
403	      };
404	
405	      ws.onclose = () => {
406	        if (endedRef.current) return;
407	        endedRef.current = true;
408	        teardown();
409	        setCallState("ended");
410	        setCaption("— call ended —");
411	      };
412	    })();
413	  }, [send, teardown]);
414	
415	  const stop = useCallback(() => {
416	    endedRef.current = true;
417	    teardown();
418	    setCallState("ended");
419	    setCaption("— call ended —");
420	  }, [teardown]);
421	
422	  const interrupt = useCallback(() => {
423	    if (stateRef.current !== "speaking") return;
424	    playbackRef.current?.stop();
425	    setCallState("interrupted");
426	    if (interruptTimerRef.current) clearTimeout(interruptTimerRef.current);
427	    interruptTimerRef.current = setTimeout(() => setCallState("listening"), 600);
428	  }, []);
429	
430	  const setMuted = useCallback((muted: boolean) => {
431	    mutedRef.current = muted;
432	    if (muted) inputRmsRef.current = 0;
433	  }, []);
434	
435	  const getInputVolume = useCallback(() => Math.min(1, inputRmsRef.current * VOL_GAIN), []);
436	  const getOutputVolume = useCallback(
437	    () => Math.min(1, (playbackRef.current?.level ?? 0) * VOL_GAIN),
438	    [],
439	  );
440	
441	  // Hang up + reset if the provider is switched away from xAI mid-session.
442	  useEffect(() => {
443	    if (active) return;
444	    if (stateRef.current !== "idle") {
445	      endedRef.current = true;
446	      teardown();
447	      setCallState("idle");
448	      setTurns([]);
449	      setCaption("press CALL to begin");
450	    }
451	  }, [active, teardown]);
452	
453	  // Cleanup on unmount.
454	  useEffect(() => () => teardown(), [teardown]);
455	
456	  return useMemo<XaiSession>(
457	    () => ({
458	      callState,
459	      turns,
460	      caption,
461	      start,
462	      stop,
463	      interrupt,
464	      setMuted,
465	      getInputVolume,
466	      getOutputVolume,
467	    }),
468	    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
469	  );
470	}
