1	// Framework-free Web Audio helpers for the xAI Grok voice engine.
2	//
3	// xAI's realtime API exchanges raw PCM16 little-endian audio as base64 strings
4	// over the WebSocket (no codec). We capture mic Float32 frames, convert to
5	// PCM16, and base64-encode for `input_audio_buffer.append`; inbound
6	// `response.output_audio.delta` chunks are the reverse. Sample rate is the
7	// browser's native AudioContext rate end-to-end — we advertise it to xAI in
8	// `session.update`, so no resampling is needed (mirrors the xai-cookbook).
9	
10	/** Float32 [-1,1] → PCM16 → base64. */
11	export function float32ToPcm16Base64(float32: Float32Array): string {
12	  const pcm16 = new Int16Array(float32.length);
13	  for (let i = 0; i < float32.length; i++) {
14	    const s = Math.max(-1, Math.min(1, float32[i]));
15	    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
16	  }
17	  return arrayBufferToBase64(pcm16.buffer);
18	}
19	
20	/** base64 PCM16 → Float32 [-1,1]. */
21	export function base64Pcm16ToFloat32(base64: string): Float32Array {
22	  const binary = atob(base64);
23	  const bytes = new Uint8Array(binary.length);
24	  for (let i = 0; i < binary.length; i++) {
25	    bytes[i] = binary.charCodeAt(i);
26	  }
27	  const pcm16 = new Int16Array(bytes.buffer);
28	  const float32 = new Float32Array(pcm16.length);
29	  for (let i = 0; i < pcm16.length; i++) {
30	    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
31	  }
32	  return float32;
33	}
34	
35	function arrayBufferToBase64(buffer: ArrayBuffer): string {
36	  const bytes = new Uint8Array(buffer);
37	  let binary = "";
38	  // Chunk to stay well under the argument-count limit of String.fromCharCode.
39	  const CHUNK = 0x8000;
40	  for (let i = 0; i < bytes.byteLength; i += CHUNK) {
41	    binary += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
42	  }
43	  return btoa(binary);
44	}
45	
46	/**
47	 * Bounded FIFO of base64 PCM16 `input_audio_buffer.append` chunks captured
48	 * BEFORE the xAI session is configured.
49	 *
50	 * xAI's "parallel initialization" guidance: open the mic immediately (in
51	 * parallel with the token mint + WS connect), buffer the user's early speech
52	 * client-side, then flush it the instant `session.updated` arrives — so the
53	 * first words spoken right after pressing CALL aren't lost. Capacity-bounded so
54	 * a stalled or failed configuration can't grow memory without limit (the oldest
55	 * chunk is dropped past `maxChunks`).
56	 */
57	export class EarlyAudioBuffer {
58	  private chunks: string[] = [];
59	  private readonly maxChunks: number;
60	
61	  /** @param maxChunks default 50 ≈ 5 s at 100 ms/chunk. */
62	  constructor(maxChunks = 50) {
63	    this.maxChunks = maxChunks;
64	  }
65	
66	  push(base64: string): void {
67	    this.chunks.push(base64);
68	    if (this.chunks.length > this.maxChunks) this.chunks.shift();
69	  }
70	
71	  /** Return everything buffered (in order) and reset — flush on session ready. */
72	  drain(): string[] {
73	    const out = this.chunks;
74	    this.chunks = [];
75	    return out;
76	  }
77	
78	  clear(): void {
79	    this.chunks = [];
80	  }
81	
82	  get size(): number {
83	    return this.chunks.length;
84	  }
85	}
86	
87	/** Root-mean-square level of a frame, ~0..1. */
88	export function calculateRms(float32: Float32Array): number {
89	  let sum = 0;
90	  for (let i = 0; i < float32.length; i++) sum += float32[i] * float32[i];
91	  return Math.sqrt(sum / float32.length);
92	}
93	
94	/**
95	 * Gap-less playback of streamed PCM16 chunks via chained AudioBufferSourceNodes.
96	 * `stop()` clears the queue + kills the current source for barge-in. `level`
97	 * exposes the currently-playing chunk's RMS so the orb can react to TTS output.
98	 */
99	export class PlaybackQueue {
100	  private ctx: AudioContext;
101	  private queue: Float32Array[] = [];
102	  private playing = false;
103	  private current: AudioBufferSourceNode | null = null;
104	  private _level = 0;
105	
106	  constructor(ctx: AudioContext) {
107	    this.ctx = ctx;
108	  }
109	
110	  enqueue(chunk: Float32Array): void {
111	    this.queue.push(chunk);
112	    if (!this.playing) {
113	      this.playing = true;
114	      this.playNext();
115	    }
116	  }
117	
118	  private playNext(): void {
119	    const chunk = this.queue.shift();
120	    if (!chunk) {
121	      this.playing = false;
122	      this.current = null;
123	      this._level = 0;
124	      return;
125	    }
126	    const buffer = this.ctx.createBuffer(1, chunk.length, this.ctx.sampleRate);
127	    buffer.getChannelData(0).set(chunk);
128	    const source = this.ctx.createBufferSource();
129	    source.buffer = buffer;
130	    source.connect(this.ctx.destination);
131	    this.current = source;
132	    this._level = calculateRms(chunk);
133	    source.onended = () => {
134	      if (this.current === source) this.current = null;
135	      this.playNext();
136	    };
137	    source.start();
138	  }
139	
140	  /** Barge-in: stop now and drop anything queued. */
141	  stop(): void {
142	    if (this.current) {
143	      try {
144	        this.current.stop();
