// Mints a short-lived fal.ai realtime JWT server-side so the browser can open
// a WebSocket to fal WITHOUT ever seeing FAL_KEY.
//
// Flow: client POSTs here → we call fal's token API with the secret key →
// return the JWT. The browser then connects with
//   new WebSocket("wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=" + jwt)
//
// The token API wants the app ALIAS only (no owner prefix): "personaplex".
// Dev only: FAL_KEY is provided via fnox (`fnox exec -- bun run dev`).

export const runtime = "nodejs";
// Never cache a freshly-minted token.
export const dynamic = "force-dynamic";

const TOKENS_URL = "https://rest.alpha.fal.ai/tokens/";
const TOKEN_TTL_SECONDS = 300;
const ALLOWED_APPS = ["personaplex"];

export async function POST(): Promise<Response> {
  const apiKey = REDACTED;
  if (!apiKey) {
    // Do not echo any key material; just say it's unset.
    return Response.json(
      { error: "FAL_KEY is not set on the server (provide it via fnox)." },
      { status: 500 },
    );
  }

  let upstream: Response;
  try {
    upstream = await fetch(TOKENS_URL, {
      method: "POST",
      headers: {
        Authorization: `Key ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        allowed_apps: ALLOWED_APPS,
        token_expiration: TOKEN_TTL_SECONDS,
      }),
    });
  } catch (err) {
    return Response.json(
      { error: `Failed to reach fal: ${err instanceof Error ? err.message : "network error"}` },
      { status: 502 },
    );
  }

  const text = await upstream.text();
  if (!upstream.ok) {
    // Surface fal's status + body (it doesn't contain our key) for debugging.
    return Response.json(
      { error: "fal token request failed", status: upstream.status, detail: text },
      { status: 502 },
    );
  }

  // fal returns the JWT as a bare JSON string ("ey…"); normalize to { token }.
  let token = text.trim();
  try {
    const parsed: unknown = JSON.parse(text);
    if (typeof parsed === "string") token = parsed;
    else if (parsed && typeof parsed === "object") {
      const d = parsed as Record<string, unknown>;
      if (typeof d.detail === "string") token = d.detail;
    }
  } catch {
    // Not JSON — treat the raw body as the token.
  }

  return Response.json(
    { token },
    { status: 200, headers: { "Cache-Control": "no-store" } },
  );
}

// fal.ai PersonaPlex agent configuration — the source of truth for what each
// persona sounds and behaves like on the hosted full-duplex PersonaPlex engine.
//
// PersonaPlex (nvidia/personaplex-7b-v1) is conditioned per SESSION, not per
// turn: a voice prompt (one of 18 presets) plus a free-text role prompt sent
// with the first WebSocket message. There is no instruction-following chat
// scaffold — the model role-plays the prompt, so prompts here read like the
// model card's examples ("You are X… your name is Y…"), short and declarative.
// There is also no firstMessage bootstrap: the model speaks first on its own
// (it was trained to open the call), and no turn detection — it is full-duplex.
//
// Mirrors xai-agent.ts: shared transport/sampling in BASE, personas override
// what personalizes them. `resolveFalAgent(personaId)` merges over BASE.

/** The 18 built-in voice-prompt presets. NAT = natural, VAR = variety; F/M. */
export type FalVoice =
  | "NATF0"
  | "NATF1"
  | "NATF2"
  | "NATF3"
  | "NATM0"
  | "NATM1"
  | "NATM2"
  | "NATM3"
  | "VARF0"
  | "VARF1"
  | "VARF2"
  | "VARF3"
  | "VARF4"
  | "VARM0"
  | "VARM1"
  | "VARM2"
  | "VARM3"
  | "VARM4";

export interface FalAgentConfig {
  /** fal app id — the WS connects to wss://fal.run/{appId}/realtime. */
  appId: string;
  /** Voice preset for the session's voice prompt. */
  voice: FalVoice;
  /** Free-text role prompt (the model role-plays this persona). */
  prompt: string;
  /** Text sampling temperature (fal default 0.7). */
  temperatureText: number;
  /** Audio sampling temperature (fal default 0.8). */
  temperatureAudio: number;
  /** Top-K for text tokens (fal default 25). */
  topKText: number;
  /** Top-K for audio tokens (fal default 250). */
  topKAudio: number;
}

// Transport + sampling settings every persona shares. Defaults follow the fal
// endpoint's own defaults; lower audio temperature is one of the few levers
// against the model's halting delivery, tune per-persona if needed.
const BASE: Omit<FalAgentConfig, "voice" | "prompt"> = {
  appId: "fal-ai/personaplex",
  temperatureText: 0.7,
  temperatureAudio: 0.8,
  topKText: 25,
  topKAudio: 250,
};

// Per-persona personality. Keyed by `Persona.id` from lib/data.ts. Voice
// presets are unlabeled beyond natural/variety + gender — the mapping below is
// a by-ear starting point; audition and reassign freely.
type PersonaAgent = Pick<FalAgentConfig, "voice" | "prompt">;

const PERSONA_AGENTS: Record<string, PersonaAgent> = {
  // Warm, calm, measured contralto — onboarding & long-form support.
  aria: {
    voice: "NATF2",
