(() => {
  // Wrap WebSocket to observe the next session's traffic.
  const Orig = window.WebSocket;
  window.__wsLog = {url:'', sent:0, recvStr:0, recvBin:0, firstBinHead:null, closes:[]};
  window.WebSocket = function(url, protos){
    const ws = protos ? new Orig(url, protos) : new Orig(url);
    window.__wsLog.url = String(url).slice(0, 60);
    const origSend = ws.send.bind(ws);
    ws.send = (d)=>{ window.__wsLog.sent++; return origSend(d); };
    ws.addEventListener('message', (ev)=>{
      if (typeof ev.data === 'string') { window.__wsLog.recvStr++; window.__wsLog.lastStr = ev.data.slice(0,200); }
      else {
        window.__wsLog.recvBin++;
        if (!window.__wsLog.firstBinHead) {
          const p = ev.data instanceof ArrayBuffer ? Promise.resolve(ev.data) : ev.data.arrayBuffer();
          p.then(ab => { window.__wsLog.firstBinHead = [...new Uint8Array(ab).slice(0,60)].map(b=>b.toString(16).padStart(2,'0')).join(' '); });
        }
      }
    });
    ws.addEventListener('close', (ev)=>window.__wsLog.closes.push(ev.code));
    return ws;
  };
  window.WebSocket.prototype = Orig.prototype;
  Object.assign(window.WebSocket, {CONNECTING:0, OPEN:1, CLOSING:2, CLOSED:3});
  // Hang up current session
  const hang=[...document.querySelectorAll('button')].find(b=>/hang|end/i.test(b.getAttribute('aria-label')||'')) || [...document.querySelectorAll('button')].find(b=>b.getAttribute('aria-label')==='Call');
  hang.click();
  return 'ws wrapped, hung up: ' + (hang.getAttribute('aria-label'));
})()

