def pcm16_bytes_to_float(payload: bytes) -> np.ndarray:
    """Raw PCM16 little-endian bytes -> float32 [-1, 1] (drops a trailing odd byte)."""
    usable = len(payload) - (len(payload) % 2)
    if usable == 0:
        return np.zeros(0, dtype=np.float32)
    return np.frombuffer(payload[:usable], dtype="<i2").astype(np.float32) / 32768.0


def float_to_pcm16_bytes(pcm: np.ndarray) -> bytes:
    """float32 [-1, 1] -> raw PCM16 little-endian bytes."""
    return (np.clip(pcm, -1.0, 1.0) * 32767.0).astype("<i2").tobytes()

