// Probe the local personaplex-mlx server's new ?format=pcm mode.
// Tag-prefixed binary frames: 0x00 handshake, 0x01 audio (raw PCM16), 0x02 text.
const CHUNK = 1920 * 2; // 80ms of PCM16 @ 24kHz
const RUN_MS = 12000;

const params = new URLSearchParams({
  voice_prompt: "NATF2.pt",
  text_prompt: "You work for First Neuron Bank and your name is Alexis Kim.",
  format: "pcm",
});
const ws = new WebSocket(`ws://localhost:8998/api/chat?${params}`);
ws.binaryType = "arraybuffer";

const silent = new Uint8Array(1 + CHUNK);
silent[0] = 0x01;

let handshakeAt = -1;
let firstAudioAt = -1;
let audioSamples = 0;
let voicedMsgs = 0;
let textBuf = "";
const t0 = Date.now();
let iv: ReturnType<typeof setInterval> | null = null;

ws.onmessage = (ev) => {
  const bytes = new Uint8Array(ev.data as ArrayBuffer);
  if (bytes.length === 0) return;
  const tag = bytes[0];
  if (tag === 0x00) {
    handshakeAt = Date.now() - t0;
    iv = setInterval(() => {
      if (ws.readyState === WebSocket.OPEN) ws.send(silent);
    }, 80);
    setTimeout(() => {
      if (iv) clearInterval(iv);
      ws.close();
    }, RUN_MS);
  } else if (tag === 0x01) {
    if (firstAudioAt < 0) firstAudioAt = Date.now() - t0;
    const n = (bytes.length - 1) >> 1;
    audioSamples += n;
    const dv = new DataView(ev.data as ArrayBuffer, 1);
    let sum = 0;
    for (let i = 0; i < n; i++) sum += (dv.getInt16(i * 2, true) / 32768) ** 2;
    if (n > 0 && Math.sqrt(sum / n) > 0.01) voicedMsgs++;
  } else if (tag === 0x02) {
    textBuf += new TextDecoder().decode(bytes.subarray(1));
  }
};

ws.onclose = () => {
  console.log(`handshake@${handshakeAt}ms first_audio@${firstAudioAt}ms`);
  console.log(`audio ${(audioSamples / 24000).toFixed(2)}s, voiced msgs=${voicedMsgs}`);
  console.log("text:", JSON.stringify(textBuf.slice(0, 200)));
  process.exit(0);
};
ws.onerror = () => console.log("ws error");

