290	        if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
291	        agentTurnIdRef.current = null;
292	        agentBufRef.current = "";
293	      };
294	
295	      const ws = new WebSocket(
296	        `${REALTIME_BASE}/${agent.appId}/realtime?fal_jwt_token=REDACTED,
297	      );
298	      ws.binaryType = "arraybuffer";
299	      wsRef.current = ws;
300	
301	      ws.onopen = () => {
302	        if (endedRef.current) return;
303	        // Kick the session with the persona config; the model greets first,
304	        // so the user is "listening" from the start.
305	        sendAudio(new Uint8Array(0));
306	        setCallState("listening");
307	        setCaption("listening…");
308	      };
309	
310	      const handleResult = (msg: FalResult) => {
311	        if (msg.status === "error" || msg.type === "x-fal-error") {
312	          // Auth/app errors are fatal (fal closes the socket after most).
313	          setCaption(`— ${msg.reason ?? msg.error ?? "fal error"} —`);
314	          return;
315	        }
316	        if (typeof msg.type === "string" && msg.type.startsWith("x-fal-")) return; // control chatter
317	        if (msg.text) pushAgentDelta(msg.text);
318	        if (msg.audio && msg.audio.length > 0) {
319	          // msgpack carries the PCM as raw bytes; tolerate a base64 string too.
320	          const chunk =
321	            typeof msg.audio === "string"
322	              ? pcm16BytesToFloat32(Uint8Array.from(atob(msg.audio), (c) => c.charCodeAt(0)))
323	              : pcm16BytesToFloat32(msg.audio);
324	          gateRef.current?.observeOutput(chunk);
325	          playbackRef.current?.enqueue(chunk);
326	          // Full-duplex: no turn events — derive speaking/listening from output
327	          // voicing, holding through the model's word-by-word pad gaps.
328	          if (calculateRms(chunk) >= VOICED_RMS) {
329	            setCallState("speaking");
330	            if (speakingTimerRef.current) clearTimeout(speakingTimerRef.current);
331	            speakingTimerRef.current = setTimeout(() => {
332	              if (!endedRef.current) setCallState("listening");
333	            }, SPEAKING_HOLD_MS);
334	            if (turnTimerRef.current) clearTimeout(turnTimerRef.current);
335	            turnTimerRef.current = setTimeout(() => {
336	              if (!endedRef.current) finalizeAgent();
337	            }, TURN_QUIET_MS);
338	          }
339	        }
340	      };
341	
342	      ws.onmessage = (event) => {
343	        if (endedRef.current) return;
344	        let msg: FalResult;
345	        try {
346	          msg =
347	            typeof event.data === "string"
348	              ? (JSON.parse(event.data) as FalResult)
349	              : (decode(new Uint8Array(event.data as ArrayBuffer)) as FalResult);
350	        } catch {
351	          return; // frame we don't understand
352	        }
353	        handleResult(msg);
354	      };
355	
356	      ws.onerror = () => {
357	        if (endedRef.current) return;
358	        endedRef.current = true;
359	        teardown();
360	        setCallState("ended");
361	        setCaption("— connection error —");
362	      };
363	
364	      ws.onclose = () => {
365	        if (endedRef.current) return;
366	        endedRef.current = true;
367	        teardown();
368	        setCallState("ended");
369	        setCaption("— call ended —");
370	      };
371	    })();
372	  }, [teardown]);
373	
374	  const stop = useCallback(() => {
375	    endedRef.current = true;
376	    teardown();
377	    setCallState("ended");
378	    setCaption("— call ended —");
379	  }, [teardown]);
380	
381	  // Full-duplex: the model yields to speech natively — just talk over it.
382	  // Stop local playback so the button still feels responsive.
383	  const interrupt = useCallback(() => {
384	    if (stateRef.current !== "speaking") return;
385	    playbackRef.current?.stop();
386	    setCallState("listening");
387	  }, []);
388	
389	  const setMuted = useCallback((muted: boolean) => {
390	    mutedRef.current = muted;
391	    if (muted) inputRmsRef.current = 0;
392	  }, []);
393	
394	  const getInputVolume = useCallback(() => Math.min(1, inputRmsRef.current * VOL_GAIN), []);
395	  const getOutputVolume = useCallback(
396	    () => Math.min(1, (playbackRef.current?.level ?? 0) * VOL_GAIN),
397	    [],
398	  );
399	
400	  // Hang up + reset if the provider is switched away from fal mid-session.
401	  useEffect(() => {
402	    if (active) return;
403	    if (stateRef.current !== "idle") {
404	      endedRef.current = true;
405	      teardown();
406	      setCallState("idle");
407	      setTurns([]);
408	      setCaption("press CALL to begin");
409	    }
410	  }, [active, teardown]);
411	
412	  // Cleanup on unmount.
413	  useEffect(() => () => teardown(), [teardown]);
414	
415	  return useMemo<FalSession>(
416	    () => ({
417	      callState,
418	      turns,
419	      caption,
420	      start,
421	      stop,
422	      interrupt,
423	      setMuted,
424	      getInputVolume,
425	      getOutputVolume,
426	    }),
427	    [callState, turns, caption, start, stop, interrupt, setMuted, getInputVolume, getOutputVolume],
428	  );
429	}
