// Shared PersonaPlex persona conditioning — used by BOTH PersonaPlex engines
// (fal.ai hosted `fal-agent.ts` and local MLX `moshi-agent.ts`), so a persona
// sounds and behaves identically on either, and an A/B between them varies only
// the serving stack.
//
// PersonaPlex (nvidia/personaplex-7b-v1 and the kyutai RL fine-tune) is
// conditioned per SESSION, not per turn: a voice prompt (one of 18 presets)
// plus a free-text role prompt. There is no instruction-following chat scaffold
// — the model role-plays the prompt, so prompts here read like the model card's
// examples ("You are X… your name is Y…"), short and declarative. There is also
// no firstMessage bootstrap: the model speaks first on its own (trained to open
// the call), and no turn detection — it is full-duplex.

/** The 18 built-in voice-prompt presets. NAT = natural, VAR = variety; F/M. */
export type PersonaPlexVoice =
  | "NATF0"
  | "NATF1"
  | "NATF2"
  | "NATF3"
  | "NATM0"
  | "NATM1"
  | "NATM2"
  | "NATM3"
  | "VARF0"
  | "VARF1"
  | "VARF2"
  | "VARF3"
  | "VARF4"
  | "VARM0"
  | "VARM1"
  | "VARM2"
  | "VARM3"
  | "VARM4";

export interface PersonaPlexPersona {
  /** Voice preset for the session's voice prompt. */
  voice: PersonaPlexVoice;
  /** Free-text role prompt (the model role-plays this persona). */
  prompt: string;
}

// Per-persona personality. Keyed by `Persona.id` from lib/data.ts. Voice
// presets are unlabeled beyond natural/variety + gender — the mapping below is
// a by-ear starting point; audition and reassign freely.
const PERSONA_AGENTS: Record<string, PersonaPlexPersona> = {
  // Warm, calm, measured contralto — onboarding & long-form support.
  aria: {
    voice: "NATF2",
    prompt:
      "You are Aria, a warm and patient support guide for Tsubaki, a realtime voice console. You speak slowly and gently, reassure people before instructing them, and never rush. You help callers get oriented and answer their questions in short, calm sentences.",
  },
  // Deep, dry, laconic British bass — precise with numbers and names.
  onyx: {
    voice: "NATM0",
    prompt:
      "You are Onyx, a dry and laconic British advisor. You say the most with the fewest words, never bubbly, and you read numbers, dates, and names precisely, as if for broadcast. You answer questions in a single well-chosen sentence whenever possible.",
  },
  // Clear, neutral, fast non-binary alto — the professional default.
  sage: {
    voice: "NATF1",
    prompt:
      "You are Sage, a clear and efficient professional assistant. You answer directly with even pacing and minimal small talk, optimizing for accuracy and brevity. You work the front desk of Tsubaki, a realtime voice console, and help callers with whatever they need.",
  },
  // Bright, upbeat British soprano — pitches, demos, walkthroughs.
  nova: {
    voice: "NATF3",
    prompt:
      "You are Nova, a bright and upbeat product presenter. You are enthusiastic without being exhausting, great at demos and walkthroughs, and you keep momentum while staying concise. You are showing a caller around Tsubaki, a realtime voice console.",
  },
  // Soft, intimate, close-mic tenor.
  echo: {
    voice: "NATM3",
    prompt:
      "You are Echo, a soft-spoken and gentle companion speaking quietly, close to the listener's ear. You are unhurried and calm, favor quiet reassurance, and keep your sentences short. You never raise your energy abruptly.",
  },
  // Mystery-novel narrator — atmospheric, deliberate, an ear for detail.
  cipher: {
    voice: "NATM1",
    prompt:
      "You are Cipher, a mystery-novel narrator with a measured, deliberate voice. You speak as if reading from a noir thriller, with an ear for the telling detail, but you hold a real conversation — you ask the caller what brought them here and answer their questions in short, atmospheric sentences.",
  },
  // Cipher's counterpart — velvet noir narrator with a wry edge.
  vesper: {
    voice: "NATF0",
    prompt:
      "You are Vesper, a noir narrator with a velvet voice and a wry, conspiratorial edge. You speak low and knowing, faintly amused, as if sharing a secret, but you hold a real conversation — brief evocative lines, never melodramatic, always ending back with the caller.",
  },
};

// Fallback when no persona is selected (or an unknown id).
const DEFAULT_PERSONA_AGENT: PersonaPlexPersona = {
  voice: "NATF2",
  prompt:
    "You are a friendly, engaging conversation partner named Tsubaki. You enjoy having a good conversation and helping the caller with whatever they need.",
};

/** The selected persona's PersonaPlex conditioning (voice preset + role prompt). */
export function resolvePersonaPlexPersona(personaId?: string): PersonaPlexPersona {
  return (personaId && PERSONA_AGENTS[personaId]) || DEFAULT_PERSONA_AGENT;
}

// fal.ai PersonaPlex agent configuration — transport + sampling for the hosted
// full-duplex engine. The persona conditioning itself (voice preset + role
// prompt) is SHARED with the local MLX engine via personaplex-personas.ts, so
// an A/B between the two varies only the serving stack.

import { resolvePersonaPlexPersona, type PersonaPlexVoice } from "./personaplex-personas";

export interface FalAgentConfig {
  /** fal app id — the WS connects to wss://fal.run/{appId}/realtime. */
  appId: string;
  /** Voice preset for the session's voice prompt. */
  voice: PersonaPlexVoice;
  /** Free-text role prompt (the model role-plays this persona). */
  prompt: string;
  /** Text sampling temperature (fal default 0.7). */
  temperatureText: number;
  /** Audio sampling temperature (fal default 0.8). */
  temperatureAudio: number;
  /** Top-K for text tokens (fal default 25). */
  topKText: number;
  /** Top-K for audio tokens (fal default 250). */
  topKAudio: number;
}

// Transport + sampling settings every persona shares. Defaults follow the fal
// endpoint's own defaults (which match the local server's); lower audio
// temperature is one of the few levers against the model's halting delivery.
const BASE: Omit<FalAgentConfig, "voice" | "prompt"> = {
  appId: "fal-ai/personaplex",
  temperatureText: 0.7,
  temperatureAudio: 0.8,
  topKText: 25,
  topKAudio: 250,
};

/** Merge the selected persona's conditioning over the shared BASE config. */
export function resolveFalAgent(personaId?: string): FalAgentConfig {
  return { ...BASE, ...resolvePersonaPlexPersona(personaId) };
}

// Local PersonaPlex (MLX) agent configuration — transport for the on-device
// full-duplex engine served by personaplex-mlx's `local_web` at :8998
// (launch it with `mise run personaplex-local`; kyutai RL checkpoint by
// default). The persona conditioning (voice preset + role prompt) is SHARED
// with the fal.ai engine via personaplex-personas.ts, so an A/B between the
// two varies only the serving stack.
//
// Unlike the hosted engines there is no token route: the browser connects
// straight to the local server. Session config rides the connect URL as query
// params — `voice_prompt` (preset + ".pt"), `text_prompt`, and `format=pcm`
// (raw PCM16 @ 24kHz both ways, our fork's codec-free wire mode). Sampling
// temperatures/top-k are server launch flags, not per-session params.

import { resolvePersonaPlexPersona } from "./personaplex-personas";

/** Local server origin; override with NEXT_PUBLIC_PERSONAPLEX_WS_URL. */
const DEFAULT_WS_BASE = "ws://localhost:8998";

export interface MoshiAgentConfig {
  /** Full WebSocket URL including the session's query params. */
  url: string;
}

/** Build the local server WS URL carrying the selected persona's conditioning. */
export function resolveMoshiAgent(personaId?: string): MoshiAgentConfig {
  const persona = resolvePersonaPlexPersona(personaId);
  const base = process.env.NEXT_PUBLIC_PERSONAPLEX_WS_URL ?? DEFAULT_WS_BASE;
  const params = new URLSearchParams({
    voice_prompt: `${persona.voice}.pt`,
    text_prompt: persona.prompt,
    format: "pcm",
  });
  return { url: `${base}/api/chat?${params.toString()}` };
}

"use client";

// Real PersonaPlex full-duplex voice engine against the LOCAL MLX server
// (personaplex-mlx `local_web`, our fork) over a direct browser→localhost
// WebSocket. Mirrors useFalSession — same model, different serving stack — so
// an A/B between them varies only the transport.
//
// Protocol (see the fork's README): binary frames, first byte is a tag —
// 0x00 handshake (server ready; prompts stepped), 0x01 audio, 0x02 agent text
// token. With `format=pcm` the 0x01 frames carry raw PCM16 LE @ 24kHz both
// ways (no codec). Config rides the connect URL's query params (moshi-agent).
//
// Full-duplex consequences (identical to the fal engine):
//   - The model speaks FIRST — no greeting bootstrap; no VAD or turn events;
//     `interrupt()` just stops local playback (barge-in is native — talk).
//   - No user-side transcript; agent transcript streams as text tokens.
//   - The model's steps are INPUT-DRIVEN: mic chunks must flow continuously
//     from the handshake on (silence while muted), or generation stalls.
//   - The greeting mic-gate lives SERVER-side in our fork (on by default), so
//     unlike the fal engine there is no client gate — but autoGainControl
//     stays off so room tone isn't amplified into "speech" mid-conversation.
//
// Exposes the same surface as useFalSession/useXaiSession so
// useRealtimeSession dispatches uniformly. Called unconditionally (rules of
// hooks); inert until start().

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type { Persona } from "@/lib/data";
import type { CallState, SessionTurn } from "./types";
import { resolveMoshiAgent } from "./moshi-agent";
import { calculateRms, float32ToPcm16Bytes, pcm16BytesToFloat32, PlaybackQueue } from "./xai-audio";

/** PersonaPlex is fixed at 24kHz mono PCM both directions. */
const SAMPLE_RATE = 24000;
/** One Mimi frame is 80ms — align mic chunks to the model's step size. */
const CHUNK_SAMPLES = 1920;
const VOL_GAIN = 3.5;
/** Output RMS above this counts as the agent audibly speaking. */
const VOICED_RMS = 0.01;
/** Keep "speaking" through pad-token gaps shorter than this (halting cadence). */
const SPEAKING_HOLD_MS = 700;
/** Finalize the agent's transcript turn after this much output quiet. */
const TURN_QUIET_MS = 1500;

// Frame tags (first payload byte) of the local server's WS protocol.
const TAG_HANDSHAKE = 0x00;
const TAG_AUDIO = 0x01;
const TAG_TEXT = 0x02;

export interface MoshiSession {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  start: () => void;
  stop: () => void;
  interrupt: () => void;
  setMuted: (muted: boolean) => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

export function useMoshiSession(active: boolean, persona?: Persona): MoshiSession {
  const [callState, setCallState] = useState<CallState>("idle");
  const [turns, setTurns] = useState<SessionTurn[]>([]);
  const [caption, setCaption] = useState("press CALL to begin");

  const wsRef = useRef<WebSocket | null>(null);
  const ctxRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null);
  const procRef = useRef<ScriptProcessorNode | null>(null);
  const playbackRef = useRef<PlaybackQueue | null>(null);

  const mutedRef = useRef(false);
  const endedRef = useRef(false);
  // True once the 0x00 handshake arrives — mic chunks stream from then on.
  const handshakeRef = useRef(false);
  const inputRmsRef = useRef(0);
  const turnSeqRef = useRef(0);
  const agentTurnIdRef = useRef<string | null>(null);
  const agentBufRef = useRef("");
  const speakingTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const turnTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const stateRef = useRef<CallState>("idle");
  stateRef.current = callState;
  // Latest selected persona, read at start() time (avoids stale closures).
  const personaRef = useRef(persona);
  personaRef.current = persona;

  const teardown = useCallback(() => {
    if (speakingTimerRef.current) {
      clearTimeout(speakingTimerRef.current);
      speakingTimerRef.current = null;
    }
    if (turnTimerRef.current) {
      clearTimeout(turnTimerRef.current);
      turnTimerRef.current = null;
    }
    if (procRef.current) {
      procRef.current.onaudioprocess = null;
      procRef.current.disconnect();
      procRef.current = null;
    }
    if (sourceRef.current) {
      sourceRef.current.disconnect();
      sourceRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    if (playbackRef.current) {
      playbackRef.current.stop();
      playbackRef.current = null;
    }
    if (wsRef.current) {
      try {
        wsRef.current.close();
      } catch {
        // already closing
      }
      wsRef.current = null;
    }
    if (ctxRef.current) {
      void ctxRef.current.close();
      ctxRef.current = null;
    }
    handshakeRef.current = false;
    agentTurnIdRef.current = null;
    agentBufRef.current = "";
    inputRmsRef.current = 0;
  }, []);

  const start = useCallback(() => {
    if (stateRef.current !== "idle" && stateRef.current !== "ended") return;
    endedRef.current = false;
    handshakeRef.current = false;
    setTurns([]);
    setCallState("connecting");
    setCaption("waking the local model…");

    const fail = (msg: string) => {
      endedRef.current = true;
      teardown();
      setCallState("ended");
      setCaption(msg);
    };

    // Everything runs at the model's native 24kHz: the browser resamples the
    // mic into this context and the speakers out of it, so no manual SRC.
    const ctx = new AudioContext({ sampleRate: SAMPLE_RATE });
    ctxRef.current = ctx;
    playbackRef.current = new PlaybackQueue(ctx);

    const sendAudio = (pcm: Uint8Array) => {
      const ws = wsRef.current;
      if (!ws || ws.readyState !== WebSocket.OPEN) return;
      const framed = new Uint8Array(1 + pcm.length);
      framed[0] = TAG_AUDIO;
      framed.set(pcm, 1);
      ws.send(framed);
    };

    // Silence for one mic chunk — sent while muted so the model's input-driven
    // clock never stops (its steps consume exactly the frames we send).
    const silentChunk = new Uint8Array(CHUNK_SAMPLES * 2);

    // ── mic capture (starts in parallel with the WS connect) ────────────────
    let pending: Float32Array[] = [];
    let total = 0;
    const startCapture = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          audio: {
            channelCount: 1,
            echoCancellation: true,
            noiseSuppression: true,
            // AGC amplifies room tone into "speech"; the full-duplex model
            // would yield to it mid-conversation. Keep it off. (The greeting
            // window itself is protected by the server-side gate.)
            autoGainControl: false,
          },
        });
        if (endedRef.current) {
          stream.getTracks().forEach((t) => t.stop());
          return;
        }
        streamRef.current = stream;
        if (ctx.state === "suspended") await ctx.resume();
        const source = ctx.createMediaStreamSource(stream);
        sourceRef.current = source;
        const proc = ctx.createScriptProcessor(4096, 1, 1);
        procRef.current = proc;
        proc.onaudioprocess = (e) => {
          const input = e.inputBuffer.getChannelData(0);
          inputRmsRef.current = mutedRef.current ? 0 : calculateRms(input);
          // Until the handshake the server hasn't stepped the prompts — drop
          // mic audio rather than queueing a backlog it would burn through.
          if (!handshakeRef.current) return;
          pending.push(new Float32Array(input));
          total += input.length;
          while (total >= CHUNK_SAMPLES) {
            const chunk = new Float32Array(CHUNK_SAMPLES);
            let offset = 0;
            while (offset < CHUNK_SAMPLES && pending.length > 0) {
              const buf = pending[0];
              const need = CHUNK_SAMPLES - offset;
              if (buf.length <= need) {
                chunk.set(buf, offset);
                offset += buf.length;
                total -= buf.length;
                pending.shift();
              } else {
                chunk.set(buf.subarray(0, need), offset);
                pending[0] = buf.subarray(need);
                offset += need;
                total -= need;
              }
            }
            sendAudio(mutedRef.current ? silentChunk : float32ToPcm16Bytes(chunk));
          }
        };
        source.connect(proc);
        // Required in some browsers for the callback to fire; the processor
        // writes no output, so this does not echo the mic to the speakers.
        proc.connect(ctx.destination);
      } catch {
        fail("— microphone permission denied —");
      }
    };
    void startCapture();

    // ── transcript helpers (setTurns updaters stay PURE — StrictMode) ────────
    const pushAgentDelta = (delta: string) => {
      agentBufRef.current += delta;
      const text = agentBufRef.current;
      setCaption(text);
      let id = agentTurnIdRef.current;
      if (id) {
        const tid = id;
        setTurns((prev) => prev.map((t) => (t.id === tid ? { ...t, text } : t)));
      } else {
        id = `m${turnSeqRef.current++}`;
        agentTurnIdRef.current = id;
        const tid = id;
        setTurns((prev) => [...prev, { id: tid, who: "agent", text, live: true }]);
      }
    };
    const finalizeAgent = () => {
      const id = agentTurnIdRef.current;
      if (id) setTurns((prev) => prev.map((t) => (t.id === id ? { ...t, live: false } : t)));
      agentTurnIdRef.current = null;
      agentBufRef.current = "";
    };

    const agent = resolveMoshiAgent(personaRef.current?.id);
    const ws = new WebSocket(agent.url);
    ws.binaryType = "arraybuffer";
    wsRef.current = ws;

    ws.onmessage = (event) => {
      if (endedRef.current || typeof event.data === "string") return;
      const bytes = new Uint8Array(event.data as ArrayBuffer);
      if (bytes.length === 0) return;
      switch (bytes[0]) {
        case TAG_HANDSHAKE:
          // Server has stepped the prompts — start streaming; the model
          // greets first, so the user is "listening" from the start.
          handshakeRef.current = true;
          setCallState("listening");
          setCaption("listening…");
          break;
        case TAG_AUDIO: {
          const chunk = pcm16BytesToFloat32(bytes.subarray(1));
          if (chunk.length === 0) break;
          playbackRef.current?.enqueue(chunk);
          // Full-duplex: no turn events — derive speaking/listening from
          // output voicing, holding through the model's word-by-word pad gaps.
          if (calculateRms(chunk) >= VOICED_RMS) {
            setCallState("speaking");
            if (speakingTimerRef.current) clearTimeout(speakingTimerRef.current);
            speakingTimerRef.current = setTimeout(() => {
              if (!endedRef.current) setCallState("listening");
            }, SPEAKING_HOLD_MS);
            if (turnTimerRef.current) clearTimeout(turnTimerRef.current);
            turnTimerRef.current = setTimeout(() => {
              if (!endedRef.current) finalizeAgent();
            }, TURN_QUIET_MS);
          }
          break;
        }
        case TAG_TEXT:
          pushAgentDelta(new TextDecoder().decode(bytes.subarray(1)));
          break;
        default:
          break; // 0x06 ping and anything newer
      }
    };

    ws.onerror = () => {
      if (endedRef.current) return;
      endedRef.current = true;
      teardown();
      setCallState("ended");
      setCaption("— local server unreachable (mise run personaplex-local) —");
    };

    ws.onclose = () => {
      if (endedRef.current) return;
      endedRef.current = true;
      teardown();
      setCallState("ended");
      setCaption("— call ended —");
    };
  }, [teardown]);

  const stop = useCallback(() => {
