(() => {
  navigator.mediaDevices.getUserMedia = async () => {
    const ac = new AudioContext({ sampleRate: 24000 });
    const osc = ac.createOscillator(); const g = ac.createGain(); g.gain.value = 0;
    const dst = ac.createMediaStreamDestination();
    osc.connect(g); g.connect(dst); osc.start();
    return dst.stream;
  };
  window.__caps = []; window.__wsSent = 0;
  const OrigCtx = window.AudioContext;
  window.AudioContext = function(opts){ const c = new OrigCtx(opts); window.__caps.push(c); return c; };
  window.AudioContext.prototype = OrigCtx.prototype;
  const origSend = WebSocket.prototype.send;
  WebSocket.prototype.send = function(d){ window.__wsSent++; return origSend.call(this, d); };
  const origConnect = AudioNode.prototype.connect;
  AudioNode.prototype.connect = function(dst, ...rest){
    const r = origConnect.call(this, dst, ...rest);
    try {
      if (dst instanceof AudioDestinationNode && !this.__isTap) {
        const ctx = this.context;
        if (!ctx.__tap) {
          const sp = ctx.createScriptProcessor(2048,1,1);
          sp.__isTap = true; ctx.__samples = [];
          sp.onaudioprocess = e => { if (ctx.__samples.length < 400) ctx.__samples.push(new Float32Array(e.inputBuffer.getChannelData(0))); };
          const tap = ctx.createGain(); tap.__isTap = true; ctx.__tap = tap;
          origConnect.call(tap, sp); origConnect.call(sp, ctx.destination);
        }
        origConnect.call(this, ctx.__tap);
      }
    } catch {}
    return r;
  };
  const nav=[...document.querySelectorAll('button')].find(b=>/PROVIDERS/.test(b.textContent)); nav.click();
  return new Promise(r=>setTimeout(()=>{
    const e=[...document.querySelectorAll('*')].filter(x=>x.childElementCount===0 && /KYUTAI/.test(x.textContent))[0];
    (e.closest('button')||e.closest('tr,div')).click();
    const s=[...document.querySelectorAll('button')].find(b=>/SESSIONS/.test(b.textContent)); s.click();
    setTimeout(()=>{ [...document.querySelectorAll('button')].find(b=>b.getAttribute('aria-label')==='Call').click(); r('instrumented + CALL'); }, 400);
  }, 400));
})()

(() => {
  const ctx = window.__caps.find(c => c.__samples && c.__samples.length > 0);
  const sent1 = window.__wsSent;
  return new Promise(res => setTimeout(() => {
    const rate = ((window.__wsSent - sent1) / 3).toFixed(1);
    if (!ctx) return res(JSON.stringify({error:'no tap', sentRate: rate}));
    const chunks = ctx.__samples;
    const n = chunks.reduce((a,c)=>a+c.length,0);
    const x = new Float32Array(n); let o=0; for (const c of chunks){ x.set(c,o); o+=c.length; }
    let first=-1, last=-1;
    for (let i=0;i<n;i+=240){ let s=0; for(let j=i;j<Math.min(i+240,n);j++) s+=x[j]*x[j]; if (Math.sqrt(s/240)>0.01){ if(first<0) first=i; last=i; } }
    let clicks=0;
    if (first>=0) for (let i=first+1;i<=last;i++){ if (Math.abs(x[i]-x[i-1])>0.15) clicks++; }
    const t=document.body.textContent; const idx=t.indexOf('LIVE TRANSCRIPT');
    res(JSON.stringify({sentPerSec: rate, voiced_s: first<0?0:((last-first)/24000).toFixed(1), clicks, transcript:t.slice(idx,idx+170)}));
  }, 3000));
})()

