1	// Mints a short-lived fal.ai realtime JWT server-side so the browser can open
2	// a WebSocket to fal WITHOUT ever seeing FAL_API_KEY.
3	//
4	// Flow: client POSTs here → we call fal's token API with the secret key →
5	// return the JWT. The browser then connects with
6	//   new WebSocket("wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=" + jwt)
7	//
8	// The token API wants the app ALIAS only (no owner prefix): "personaplex".
9	// Dev only: FAL_API_KEY is provided via fnox (`fnox exec -- bun run dev`).
10	
11	export const runtime = "nodejs";
12	// Never cache a freshly-minted token.
13	export const dynamic = "force-dynamic";
14	
15	const TOKENS_URL = "https://rest.alpha.fal.ai/tokens/";
16	const TOKEN_TTL_SECONDS = 300;
17	const ALLOWED_APPS = ["personaplex"];
18	
19	export async function POST(): Promise<Response> {
20	  const apiKey = process.env.FAL_API_KEY;
21	  if (!apiKey) {
22	    // Do not echo any key material; just say it's unset.
23	    return Response.json(
24	      { error: "FAL_API_KEY is not set on the server (provide it via fnox)." },
25	      { status: 500 },
26	    );
27	  }
28	
29	  let upstream: Response;
30	  try {
31	    upstream = await fetch(TOKENS_URL, {
32	      method: "POST",
33	      headers: {
34	        Authorization: `Key ${apiKey}`,
35	        "Content-Type": "application/json",
36	      },
37	      body: JSON.stringify({
38	        allowed_apps: ALLOWED_APPS,
39	        token_expiration: TOKEN_TTL_SECONDS,
40	      }),
41	    });
42	  } catch (err) {
43	    return Response.json(
44	      {
45	        error: `Failed to reach fal: ${err instanceof Error ? err.message : "network error"}`,
46	      },
47	      { status: 502 },
48	    );
49	  }
50	
51	  const text = await upstream.text();
52	  if (!upstream.ok) {
53	    // Surface fal's status + body (it doesn't contain our key) for debugging.
54	    return Response.json(
55	      {
56	        error: "fal token request failed",
57	        status: upstream.status,
58	        detail: text,
59	      },
60	      { status: 502 },
61	    );
62	  }
63	
64	  // fal returns the JWT as a bare JSON string ("ey…"); normalize to { token }.
65	  let token = text.trim();
66	  try {
67	    const parsed: unknown = JSON.parse(text);
68	    if (typeof parsed === "string") token = parsed;
69	    else if (parsed && typeof parsed === "object") {
70	      const d = parsed as Record<string, unknown>;
71	      if (typeof d.detail === "string") token = d.detail;
72	    }
73	  } catch {
74	    // Not JSON — treat the raw body as the token.
75	  }
76	
77	  return Response.json({ token }, { status: 200, headers: { "Cache-Control": "no-store" } });
78	}
