// Verifies a fal realtime JWT authorizes the personaplex WebSocket.
// Usage: bun ws-auth-probe.ts <token-file>
const token = (await Bun.file(process.argv[2]).text()).trim();
const url = `wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=REDACTED;

const ws = new WebSocket(url);
ws.binaryType = "arraybuffer";
const t0 = Date.now();
let messages = 0;

ws.onopen = () => console.log(`[${Date.now() - t0}ms] OPEN`);
ws.onmessage = (ev) => {
  messages++;
  const size = ev.data instanceof ArrayBuffer ? ev.data.byteLength : String(ev.data).length;
  if (messages <= 3) console.log(`[${Date.now() - t0}ms] MESSAGE #${messages} (${size} bytes)`);
};
ws.onclose = (ev) => {
  console.log(`[${Date.now() - t0}ms] CLOSE code=${ev.code} reason=${JSON.stringify(ev.reason)} messages=${messages}`);
  process.exit(ev.code === 1000 || messages > 0 ? 0 : 1);
};
ws.onerror = () => console.log(`[${Date.now() - t0}ms] ERROR`);

setTimeout(() => {
  console.log(`[timeout] still ${ws.readyState === 1 ? "OPEN (authorized)" : `state=${ws.readyState}`}, messages=${messages}`);
  ws.close();
  setTimeout(() => process.exit(0), 500);
}, 8000);

