// Never cache a freshly-minted token.
export const dynamic = "force-dynamic";

const TOKENS_URL = "https://rest.fal.ai/tokens/realtime";
const TOKEN_TTL_SECONDS = 300;
const APP = "fal-ai/personaplex/realtime";

