45	const VOL_GAIN = 3.5;
46	/** Output RMS above this counts as the agent audibly speaking. */
47	const VOICED_RMS = 0.01;
48	/** Keep "speaking" through pad-token gaps shorter than this (halting cadence). */
49	const SPEAKING_HOLD_MS = 700;
50	/** Finalize the agent's transcript turn after this much output quiet. */
