1	// fal.ai PersonaPlex agent configuration — transport + sampling for the hosted
2	// full-duplex engine. The persona conditioning itself (voice preset + role
3	// prompt) is SHARED with the local MLX engine via personaplex-personas.ts, so
4	// an A/B between the two varies only the serving stack.
5	
6	import { resolvePersonaPlexPersona, type PersonaPlexVoice } from "./personaplex-personas";
7	
8	export interface FalAgentConfig {
9	  /** fal app id — the WS connects to wss://fal.run/{appId}/realtime. */
10	  appId: string;
11	  /** Voice preset for the session's voice prompt. */
12	  voice: PersonaPlexVoice;
13	  /** Free-text role prompt (the model role-plays this persona). */
14	  prompt: string;
15	  /** Text sampling temperature (fal default 0.7). */
16	  temperatureText: number;
17	  /** Audio sampling temperature (fal default 0.8). */
18	  temperatureAudio: number;
19	  /** Top-K for text tokens (fal default 25). */
20	  topKText: number;
21	  /** Top-K for audio tokens (fal default 250). */
22	  topKAudio: number;
23	}
24	
25	// Transport + sampling settings every persona shares. Defaults follow the fal
26	// endpoint's own defaults (which match the local server's); lower audio
27	// temperature is one of the few levers against the model's halting delivery.
28	const BASE: Omit<FalAgentConfig, "voice" | "prompt"> = {
29	  appId: "fal-ai/personaplex",
30	  temperatureText: 0.7,
31	  temperatureAudio: 0.8,
32	  topKText: 25,
33	  topKAudio: 250,
34	};
35	
36	/** Merge the selected persona's conditioning over the shared BASE config. */
37	export function resolveFalAgent(personaId?: string): FalAgentConfig {
38	  return { ...BASE, ...resolvePersonaPlexPersona(personaId) };
39	}
