// Probes the fal PersonaPlex realtime socket for greeting behavior.
// Usage: bun fal-greeting-probe.ts <mode>
//   mode "kick"    — replicate the client: empty-audio kick on open, then 80ms silence chunks
//   mode "nokick"  — no kick, just continuous 80ms silence chunks
//   mode "kickonly"— empty-audio kick, then NOTHING (does the server step at all?)
import { decode, encode } from "@msgpack/msgpack";

const mode = process.argv[2] ?? "kick";
const RUN_MS = 20000;
const CHUNK_BYTES = 1920 * 2; // one 80ms Mimi frame of PCM16 @24kHz

const config = {
  prompt:
    "You work for Tsubaki which is a realtime voice console and your name is Sage. You answer the front desk. You are clear, neutral, and efficient, with even pacing and minimal small talk, and you answer directly and move on. Information: Tsubaki lets the caller talk with different personas over different voice providers; personas and providers are switched from the console sidebar.",
  voice: "VARM1",
  temperature_text: 0.7,
  temperature_audio: 0.8,
  top_k_text: 25,
  top_k_audio: 250,
};

const tokenRes = await fetch("http://localhost:3000/api/fal/token", { method: "POST" });
const { token } = (await tokenRes.json()) as { token: string };

const ws = new WebSocket(
  `wss://fal.run/fal-ai/personaplex/realtime?fal_jwt_token=REDACTED,
);
ws.binaryType = "arraybuffer";
const t0 = Date.now();
const ts = () => `[${String(Date.now() - t0).padStart(5)}ms]`;

let audioBytes = 0;
let audioMsgs = 0;
let firstAudioAt = -1;
let text = "";
let timer: ReturnType<typeof setInterval> | null = null;

ws.onopen = () => {
  console.log(`${ts()} OPEN mode=${mode}`);
  if (mode === "kick" || mode === "kickonly") {
    ws.send(encode({ ...config, audio: new Uint8Array(0) }));
    console.log(`${ts()} sent empty-audio kick`);
  }
  if (mode !== "kickonly") {
    const silent = new Uint8Array(CHUNK_BYTES);
    timer = setInterval(() => {
      if (ws.readyState === WebSocket.OPEN) ws.send(encode({ ...config, audio: silent }));
    }, 80);
  }
};

ws.onmessage = (ev) => {
  let msg: Record<string, unknown>;
  try {
    msg =
      typeof ev.data === "string"
        ? (JSON.parse(ev.data) as Record<string, unknown>)
        : (decode(new Uint8Array(ev.data as ArrayBuffer)) as Record<string, unknown>);
  } catch {
    console.log(`${ts()} undecodable frame (${(ev.data as ArrayBuffer).byteLength ?? "?"} bytes)`);
    return;
  }
  const { audio, text: t, ...rest } = msg;
  if (audio instanceof Uint8Array && audio.length > 0) {
    audioMsgs++;
    audioBytes += audio.length;
    if (firstAudioAt < 0) {
      firstAudioAt = Date.now() - t0;
      console.log(`${ts()} FIRST AUDIO (${audio.length} bytes)`);
    }
  }
  if (typeof t === "string" && t) {
    text += t;
    process.stdout.write(t);
  }
  const restKeys = Object.keys(rest).filter((k) => rest[k] !== undefined && rest[k] !== null);
  if (restKeys.length > 0 && !(audio instanceof Uint8Array)) {
    console.log(`${ts()} control:`, JSON.stringify(rest).slice(0, 300));
  }
};

ws.onclose = (ev) => console.log(`\n${ts()} CLOSE code=${ev.code} reason=${JSON.stringify(ev.reason)}`);
ws.onerror = () => console.log(`${ts()} ERROR`);

setTimeout(() => {
  if (timer) clearInterval(timer);
  console.log(
    `\n${ts()} SUMMARY mode=${mode} firstAudio=${firstAudioAt}ms audioMsgs=${audioMsgs} audioSecs=${(audioBytes / 2 / 24000).toFixed(1)} text=${JSON.stringify(text.slice(0, 200))}`,
  );
  ws.close();
  setTimeout(() => process.exit(0), 500);
}, RUN_MS);

